<?php
namespace App\Services; use App\Models\Order; use Illuminate\Support\Facades\Http; use RuntimeException;
class CourierService { public function createShipment(Order $order):array { if(!config('services.courier.enabled')) throw new RuntimeException('Courier API is not enabled.'); $r=Http::timeout(20)->withToken(config('services.courier.api_key'))->post(rtrim(config('services.courier.base_url'),'/').'/orders',[ 'invoice'=>$order->order_number,'recipient_name'=>$order->customer_name,'recipient_phone'=>$order->phone,'recipient_address'=>$order->address.', '.$order->area.', '.$order->district,'amount'=>(float)$order->total,'cod_amount'=>$order->payment_method==='cod'?(float)$order->total:0 ]); if(!$r->successful()) throw new RuntimeException('Courier booking failed: '.$r->body()); return $r->json(); } }
